SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT
  (SELECT COUNT(*) FROM comments WHERE PostId = (SELECT Id FROM posts WHERE Title = 'Clustering 1D data')) AS comment_count,
  (SELECT COUNT(*) FROM posts WHERE ParentId = (SELECT Id FROM posts WHERE Title = 'Clustering 1D data')) AS answer_count;

SELECT ExcerptPostId, WikiPostId
FROM tags
WHERE TagName = 'sample';

SELECT A3 AS branch_location, A2 AS district_name
FROM district
WHERE A13 = (SELECT MAX(A13) FROM district);

SELECT 100.0 * COUNT(DISTINCT CASE WHEN b.bond_type = '#' THEN m.molecule_id END) / COUNT(DISTINCT m.molecule_id)
FROM molecule m
LEFT JOIN bond b ON b.molecule_id = m.molecule_id;

SELECT SUM(CASE WHEN molecule.label = '+' AND atom.element = 'cl' THEN 1 ELSE 0 END) * 100.0 / COUNT(molecule.molecule_id) AS percentage
FROM molecule
JOIN atom ON molecule.molecule_id = atom.molecule_id;

SELECT MAX(frpm."Free Meal Count (K-12)" * 1.0 / frpm."Enrollment (K-12)") AS max_eligible_free_rate_k12
