SELECT COUNT(comments.Id) AS total_comments
FROM comments
WHERE comments.UserId = 13;

SELECT u.DisplayName
FROM users AS u
WHERE u.Views = (SELECT MAX(u2.Views) FROM users AS u2);

SELECT
  (SELECT COUNT(*) FROM comments AS c WHERE c.PostId = (SELECT p.Id FROM posts AS p WHERE p.Title = 'Clustering 1D data')) AS CommentCount,
  (SELECT COUNT(*) FROM posts AS a WHERE a.ParentId = (SELECT p.Id FROM posts AS p WHERE p.Title = 'Clustering 1D data') AND a.PostTypeId = 2) AS AnswerCount;

SELECT d.A3 AS branch_location, d.A2 AS district_name
