FROM Laboratory
WHERE Laboratory."U-PRO" > 0 AND Laboratory."U-PRO" < 30;

SELECT 100.0 * COUNT(DISTINCT b.molecule_id) / COUNT(DISTINCT m.molecule_id) AS percent_triple_bond
FROM molecule m
LEFT JOIN bond b ON b.molecule_id = m.molecule_id AND b.bond_type = '#';

SELECT CAST(SUM(bond.bond_type = ' = ') AS REAL) / COUNT(bond.bond_id) AS percent
FROM bond
WHERE bond.molecule_id = 'TR047';

SELECT SUM(CASE WHEN molecule.label = '+' AND atom.element = 'h' THEN 1 ELSE 0 END) * 100.0 / COUNT(molecule.molecule_id) AS percentage
FROM molecule
JOIN atom ON molecule.molecule_id = atom.molecule_id;

SELECT CASE WHEN m.label = '+' THEN 'yes' ELSE 'no' END AS carcinogenic
FROM molecule m
WHERE m.molecule_id = 'TR124';

SELECT
  (SELECT COUNT(DISTINCT b.molecule_id) FROM bond AS b WHERE b.bond_type = ' = ') AS double_bond_molecule_count,
  (SELECT COUNT(DISTINCT b.molecule_id) FROM bond AS b JOIN molecule AS m ON b.molecule_id = m.molecule_id WHERE b.bond_type = ' = ' AND m.label = '+') AS carcinogenic_double_bond_molecule_count;

