FROM gasstations gs
WHERE gs.Country = 'Slovakia';

SELECT 100.0 * COUNT(CASE WHEN gs.Segment = 'Premium' THEN 1 END) / COUNT(*) AS premium_percentage
FROM gasstations gs
WHERE gs.Country = 'SVK';

SELECT pa.player_api_id
FROM Player_Attributes AS pa
WHERE pa.overall_rating = (SELECT MAX(pa2.overall_rating) FROM Player_Attributes AS pa2);

SELECT CAST(SUM(CASE WHEN P.height < 180 AND PA.overall_rating > 70 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(P.id)
FROM Player P
JOIN Player_Attributes PA ON P.player_api_id = PA.player_api_id;

SELECT D1.district_id, D1.A2
FROM district AS D1
WHERE D1.A13 = (SELECT MAX(D2.A13) FROM district AS D2);

SELECT
  (SELECT COUNT(*) FROM attendance a JOIN member m ON a.link_to_member = m.member_id WHERE m.first_name = 'Luisa' AND m.last_name = 'Guidi') AS num_events_attended,
  (SELECT major.major_name FROM member m JOIN major ON m.link_to_major = major.major_id WHERE m.first_name = 'Luisa' AND m.last_name = 'Guidi') AS major_name;

SELECT SUM(member.position = 'Member' AND major.major_name = 'Business') * 100.0 / COUNT(member.member_id) AS percentage
FROM member
JOIN major ON member.link_to_major = major.major_id;

SELECT SUM(b.remaining < 0) * 100.0 / COUNT(e.event_id) AS percentage_over_budget
FROM event AS e
JOIN budget AS b ON b.link_to_event = e.event_id;

SELECT event_id, location, status
FROM event
WHERE event_date BETWEEN '2019-11-01' AND '2020-03-31';

SELECT SUM(CASE WHEN p.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) - SUM(CASE WHEN p.publisher_name = 'DC Comics' THEN 1 ELSE 0 END) AS publisher_difference
FROM superhero s
JOIN publisher p ON s.publisher_id = p.id;

SELECT CASE WHEN "T-CHO" < 250 THEN 'Yes' ELSE 'No' END AS normal_level
FROM Laboratory
WHERE ID = 2927464 AND Date = '1995-09-04';

SELECT ROUND(100.0 * SUM(bond.bond_type = '=') / COUNT(bond.bond_id), 5) AS percent
FROM bond
WHERE bond.molecule_id = 'TR008';

SELECT ROUND(SUM(CASE WHEN atom.element = 'h' THEN 1 ELSE 0 END) * 100.0 / COUNT(atom.atom_id), 4) AS percent
FROM atom
WHERE atom.molecule_id = 'TR206';

SELECT COUNT(atom.atom_id)
FROM atom
WHERE atom.element IN ('c', 'h');

SELECT DISTINCT b.bond_type
FROM bond b
WHERE b.molecule_id BETWEEN 'TR000' AND 'TR050';

SELECT CAST(COUNT(DISTINCT CASE WHEN T1.label = '+' AND T2.element = 'cl' THEN T1.molecule_id END) AS REAL) * 100.0 / COUNT(DISTINCT T1.molecule_id) AS percentage
FROM molecule AS T1
JOIN atom AS T2 ON T1.molecule_id = T2.molecule_id;
